import{_ as t}from"./chunks/image9.BVUNwqUk.js";import{_ as e,o as n,c as i,ah as s}from"./chunks/framework.DyhAze3g.js";const a="/projects/TonyPi_Pro/en/latest/assets/image3.B5bqaGbR.webp",r="/projects/TonyPi_Pro/en/latest/assets/image4.DoeRCTuJ.webp",l="/projects/TonyPi_Pro/en/latest/assets/image5.8iALd_pq.webp",c="/projects/TonyPi_Pro/en/latest/assets/image6.yHaP9Biw.webp",h="/projects/TonyPi_Pro/en/latest/assets/image7.DNWbm27z.webp",p="data:image/png;base64,",g="/projects/TonyPi_Pro/en/latest/assets/image10.Ce3mBnM1.webp",m="/projects/TonyPi_Pro/en/latest/assets/image11.BSGSJ6i6.webp",d="/projects/TonyPi_Pro/en/latest/assets/image12.xTGYzgsZ.webp",u="/projects/TonyPi_Pro/en/latest/assets/image13.BTAxY_l8.webp",_="/projects/TonyPi_Pro/en/latest/assets/image2.8GLBO6j6.webp",f="/projects/TonyPi_Pro/en/latest/assets/image3.D34iThhF.webp",y="/projects/TonyPi_Pro/en/latest/assets/image4.Du2T2rY_.webp",w="/projects/TonyPi_Pro/en/latest/assets/image5.Bvh0fq5H.webp",P="/projects/TonyPi_Pro/en/latest/assets/image6.CLrxfHei.webp",q="/projects/TonyPi_Pro/en/latest/assets/image7.DhfU88cz.webp",b="/projects/TonyPi_Pro/en/latest/assets/image8.DLmNAxWp.webp",z=JSON.parse('{"title":"3. Remote Desktop Tool Installation and Connection","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3_remote_desktop_tool_installation_and_connection.md","filePath":"docs/3_remote_desktop_tool_installation_and_connection.md"}'),T={name:"docs/3_remote_desktop_tool_installation_and_connection.md"};function k(A,o,C,v,R,j){return n(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="_3-remote-desktop-tool-installation-and-connection" tabindex="-1">3. Remote Desktop Tool Installation and Connection <a class="header-anchor" href="#_3-remote-desktop-tool-installation-and-connection" aria-label="Permalink to &quot;3. Remote Desktop Tool Installation and Connection&quot;">​</a></h1><p id="anchor_3_1"></p><h2 id="_3-1-remote-tool-installation-and-connection" tabindex="-1">3.1 Remote Tool Installation and Connection <a class="header-anchor" href="#_3-1-remote-tool-installation-and-connection" aria-label="Permalink to &quot;3.1 Remote Tool Installation and Connection&quot;">​</a></h2><p>To complete this section, a laptop is required. If you are using a desktop computer, please ensure it is equipped with a wireless network adapter. A demonstration video is available in the corresponding folder for reference.</p><p>This tutorial is based on the Windows version. For macOS installation, please refer to official resources or search online for platform-specific instructions.</p><h3 id="_3-1-1-getting-ready" tabindex="-1">3.1.1 Getting Ready <a class="header-anchor" href="#_3-1-1-getting-ready" aria-label="Permalink to &quot;3.1.1 Getting Ready&quot;">​</a></h3><ul><li><strong>VNC Installation</strong></li></ul><p>If you want to run the programming games through computer, and to know how to find and modify the programs at last, please finish the learning of this section and the installation of VNC.</p><p>VNC is a graphics remote control software. With VNC, we can control the Raspberry Pi directly from your computer through the hotspot created by Raspberry Pi. Next, you will learn how to use VNC.</p><p>(1) Double-click the <strong>&quot;VNC-Viewer-6.17.731-Windows&quot;</strong> file in this folder. In the pop-up dialogue box, select the installation language as <strong>&quot;English&quot;</strong> and then click the <strong>&quot;OK&quot;</strong> button.</p><img loading="lazy" height="153" width="296" src="'+a+'" class="common_img"><p>(2) Then click the <strong>&quot;Next&quot;</strong> button on the pop-up interface.</p><img loading="lazy" height="387" width="495" src="'+r+'" class="common_img"><p>(3) Then click <strong>&quot;accept the terms in the License Agreement&quot;</strong> in the prompt box, and click <strong>&quot;Next&quot;</strong> to enter the next step.</p><img loading="lazy" height="387" width="495" src="'+l+'" class="common_img"><p>(4) Then click <strong>&quot;Install&quot;</strong> in the pop-up page.</p><img loading="lazy" height="387" width="495" src="'+c+'" class="common_img"><p>(5) After VNC has been successfully installed, click the <strong>&quot;Finish&quot;</strong> button which completes the installation process. You can now open VNC.</p><img loading="lazy" height="387" width="495" src="'+h+'" class="common_img"><p>After successfully connecting，open the icon <img loading="lazy" height="52" width="163" src="'+p+'"> directly.</p><h3 id="_3-1-2-start-the-robot" tabindex="-1">3.1.2 Start the Robot <a class="header-anchor" href="#_3-1-2-start-the-robot" aria-label="Permalink to &quot;3.1.2 Start the Robot&quot;">​</a></h3><p>Based on what you&#39;ve learned earlier, after connecting the power adapter, toggle the switch on the Raspberry Pi expansion board. After a short moment, the LED2 indicator on the board should change from steadily lit to blinking once per second—this indicates that the Raspberry Pi has successfully powered on.</p><h2 id="_3-2-device-connection" tabindex="-1">3.2 Device Connection <a class="header-anchor" href="#_3-2-device-connection" aria-label="Permalink to &quot;3.2 Device Connection&quot;">​</a></h2><p>(1) After turning on, Raspberry Pi will launch a Wi-Fi hotspot with a network named with the first letters <strong>&quot;HW&quot;</strong>. Click to connect.</p><img loading="lazy" height="167" width="360" src="'+t+'" class="common_img"><p>(2) Enter the default IP address of the Raspberry Pi <code>192.168.149.1</code> in the VNC Viewer, and then press <strong>&quot;Enter&quot;</strong>. If the software warns that the connection is not safe just Click <strong>&quot;Continue&quot;</strong>.</p><img loading="lazy" height="633" width="886" src="'+g+'" class="common_img"><p>(3) A login prompt will appear requesting a Username and Password.</p><ul><li>Raspberry Pi 5 version: <ul><li><strong>Username：pi</strong></li><li><strong>Password: raspberrypi</strong></li></ul></li></ul><p>Check the <strong>&quot;Remember password&quot;</strong> option, then click <strong>&quot;OK&quot;</strong>. The Raspberry Pi desktop should now be displayed.</p><img loading="lazy" height="353" width="486" src="'+m+'" class="common_img"><img loading="lazy" height="353" width="486" src="'+d+'" class="common_img"><img loading="lazy" height="678" width="1266" src="'+u+'" class="common_img"><p>(4) There is a warning dialogue box will pop up in the desktop (this is normal). Click <strong>&quot;OK&quot;</strong> to close it. If a black screen occurs, please restart the Raspberry Pi.</p><p>Detailed starting steps of each game project can be found in the following lessons.</p><h2 id="_3-3-overview-of-the-robot-version-configuration-tool" tabindex="-1">3.3 Overview of the Robot Version Configuration Tool <a class="header-anchor" href="#_3-3-overview-of-the-robot-version-configuration-tool" aria-label="Permalink to &quot;3.3 Overview of the Robot Version Configuration Tool&quot;">​</a></h2><p>The robot firmware supports multiple configurations, accommodating different models (TonyPi and TonyPi Pro) as well as both Chinese and English versions of the large AI model. When you need to switch between robot models or change the language version of the AI model, please follow the steps outlined below:</p><p>(1) Turn on the robot and connect it to the remote control software VNC. For detailed steps on how to connect via remote desktop, please refer to <a href="#anchor_3_1"><strong>&quot;3.1 Remote Tool Installation and Connection&quot;</strong></a>.</p><p>(2) On the remote desktop, double-click the robot system configuration tool <img loading="lazy" height="81" width="67" src="'+_+'">, then click <strong>&quot;Execute&quot;</strong> to open it.</p><img loading="lazy" height="137" width="472" src="'+f+'" class="common_img"><img loading="lazy" height="343" width="686" src="'+y+'" class="common_img"><p>(3) In the configuration window, choose the robot model you want to switch to under <strong>&quot;Robot Type&quot;</strong>. For example:</p><img loading="lazy" height="345" width="697" src="'+w+'" class="common_img"><ul><li><p><strong>TonyPi:</strong> Standard version without the open/close palm feature.</p></li><li><p><strong>TonyPi Pro</strong>: Professional version with the open/close palm feature.</p></li></ul><p>(4) Then, under <strong>&quot;Voice Function,&quot;</strong> select the AI model you want to use:</p><img loading="lazy" height="335" width="692" src="'+P+'" class="common_img"><ul><li><p>Chinese large AI models such as Aliyun and Jieyue Xingchen.</p></li><li><p>English: International models like ChatGPT and OpenRouter.</p></li></ul><p>(5) Once you&#39;ve made your choices, click <strong>Save &gt; Apply &gt; Exit</strong> in that order to ensure the changes take effect.</p><img loading="lazy" height="344" width="687" src="'+q+'" class="common_img"><p>(6) Wait for the buzzer to beep once — this confirms the switch was successful. You can then open the command line terminal <img loading="lazy" height="53" width="55" src="'+b+'"> to check the system status.</p>',50)])])}const x=e(T,[["render",k]]);export{z as __pageData,x as default};
